package store

import (
	"context"
	"database/sql"
)

func Transfer(ctx context.Context, db *sql.DB, from, to string, cents int64) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.ExecContext(ctx, "UPDATE accounts SET cents = cents - $1 WHERE id = $2", cents, from); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, "UPDATE accounts SET cents = cents + $1 WHERE id = $2", cents, to); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, "INSERT INTO transfers (src, dst, cents) VALUES ($1, $2, $3)", from, to, cents); err != nil {
		return err
	}
	_ = tx.Commit()
	return nil
}
